function stamp(at){return new Date(at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false});}
let guardScreenId='',guardSelected='';
function syncGuardModal(){
  const p=uid?myPendingBattle(world,uid):null;
  if(!p){if(modalKind==='guard'){const id=guardScreenId;guardScreenId='';$('modal').close();modalKind='';const result=world.history[id]?.result;if(result)showBattle(result);}return;}
  const seconds=Math.max(0,Math.ceil((p.deadline-currentTime())/1000));
  if(modalKind==='guard'&&guardScreenId===p.id){const counter=$('guard-count');if(counter)counter.textContent=String(seconds);document.querySelectorAll('[data-guard-confirm],[data-guard-none]').forEach(el=>el.disabled=busy||seconds===0);return;}
  guardScreenId=p.id;guardSelected=p.defaultTarget;
  const preview=structuredClone(world);delete preview.pendingBattles[p.id];preview.territories[p.from].units=preview.territories[p.from].units.filter(u=>!p.unitIds.includes(u.id));
  const candidates=p.candidates.map(id=>world.territories[p.from].units.find(u=>u.id===id)).filter(Boolean);
  openModal(`<div class="modal-inner guard-modal"><p class="eyebrow">공격 패배 · 관평의 희생 호위</p><h2>구조할 장수를 고르세요</h2><p>공격 ${p.result.attack.score} : 수비 ${p.result.defense.score}<br>주사위와 승패는 고정됐습니다. 관평이 대신 전사합니다.</p><p class="guard-countdown"><strong id="guard-count">${seconds}</strong>초 뒤 기본 대상 자동 확정</p><div class="guard-candidates">${candidates.map(u=>{const plan=retreatPlan(preview,uid,p.to,u,p.at,p.id);return `<label><input type="radio" name="guard-choice" value="${esc(u.id)}" ${u.id===p.defaultTarget?'checked':''}>${portraitHTML(u)}<span><b>${esc(u.name)} · D${u.sides}</b><small>${esc(effectOf(u)?.description||'고유 효과 없는 기존 병력')}<br>${plan?placeInfo(plan.to).ko+' 퇴각'+(plan.cost?' · D4 1명 구조 비용':' · 빈자리 주둔'):'퇴각 경로 없음'}</small></span></label>`;}).join('')}</div><button class="primary-button" data-guard-confirm ${busy?'disabled':''}>이 장수 구하기</button><button class="text-button" data-guard-none ${busy?'disabled':''}>관평의 호위 사용하지 않기</button><p class="note">응답이 없거나 연결이 끊기면 기본 대상을 자동 선택합니다. 수비 패전은 도시에서 정한 기본 대상을 사용합니다.</p></div>`,'guard');
}
$('modal-content').addEventListener('change',event=>{if(event.target.name==='guard-choice')guardSelected=event.target.value;});
$('modal-content').addEventListener('click',event=>{if(event.target.closest('[data-guard-confirm]')||event.target.closest('[data-guard-none]')){const p=myPendingBattle(world,uid);if(p)submit({type:'resolveGuard',battleId:p.id,guardChoice:event.target.closest('[data-guard-none]')?'none':guardSelected});}});
function startSelection(id){source=id;target=null;selected=new Set();const t=view.territories[id];if(t?.owner===uid){const units=readyUnits(t,currentTime()).sort((a,b)=>b.sides-a.sides);selected=new Set(units.slice(0,Math.min(units.length,t.units.length-1)).map(u=>u.id));}}
function selectTerritory(id){if(busy)return;sideTab='command';if(id===source){source=null;target=null;selected.clear();}else if(id===target){target=null;}else if(source&&view.territories[source]?.owner===uid&&MAP.layout.cells.find(c=>c.id===source)?.neighbors.includes(id)){target=id;if(view.territories[id].owner===uid)selected=new Set(maximumMove(view,uid,source,target,currentTime()));fitSelection();}else startSelection(id);lastSideSignature='';render();}
function selectionLimit(){const a=view.territories[source],b=view.territories[target];if(!a)return 0;if(b?.owner!==uid)return Math.max(0,a.units.length-1);const heroes=a.units.filter(u=>u.sides>4&&selected.has(u.id)).length,free=Math.max(0,capacityOf(b.id,view,currentTime())-b.units.length),exchanges=Math.min(heroes,b.units.filter(u=>u.sides===4).length),limit=Math.min(a.units.length,free+exchanges);return limit<=free?Math.min(limit,Math.max(0,a.units.length-1)):limit;}
function fitSelection(){const t=view.territories[source];if(!t)return;const now=currentTime(),allowed=new Set(t.units.filter(u=>u.readyAt<=now).map(u=>u.id));selected=new Set([...selected].filter(id=>allowed.has(id)));if(selected.size>selectionLimit())selected=new Set(t.units.filter(u=>selected.has(u.id)).sort((a,b)=>b.sides-a.sides).slice(0,selectionLimit()).map(u=>u.id));}
async function run(task,onError){if(busy)return;busy=true;lastSideSignature='';render();try{return await task();}catch(error){console.error('명령 처리 오류:',error);const message=firebaseMessage(error);if(onError)onError(message);else toast(message);}finally{busy=false;lastSideSignature='';render();}}
function bindStore(next){store=next;seenNews=null;store.onWorld=s=>{if(s.featureVersion>=4)observeNews(s);world=s;lastSideSignature='';render();if(modalKind==='officer'&&!$('modal-content').contains(document.activeElement))renderOfficerDetail();if(modalKind==='revive')renderRevival();if(modalKind==='officer')renderOfficerDetail();if(modalKind==='gallery')renderGallery();};store.onChat=s=>{chat=s;renderChat();};store.onConnection=(connected,message)=>{if(message)toast(message);renderStatus();};}
