  const scroll=$('command-content').scrollTop,rolesBefore=$('command-content').querySelector('.role-controls'),draft=rolesBefore?{tid:rolesBefore.dataset.territory,version:rolesBefore.dataset.roleVersion,open:rolesBefore.open,values:[...rolesBefore.querySelectorAll('select')].map(el=>[el.id,el.value])}:null;renderSide();const rolesAfter=$('command-content').querySelector('.role-controls');if(!busy&&draft&&rolesAfter&&draft.tid===rolesAfter.dataset.territory&&draft.version===rolesAfter.dataset.roleVersion){rolesAfter.open=draft.open;for(const [id,value] of draft.values)if($(id))$(id).value=value;}$('command-content').scrollTop=scroll;renderFooter();
