  syncGuardModal();const ruler=uid?livingUnits(world,uid).find(u=>u.sides===20):null;$('ruler-state').textContent=!uid?'천하가 당신을 기다립니다':ruler?'군주 생존 · D20':mine.length?'군주 전사 · 영토에서 부활 가능':'새로운 깃발을 준비하세요';
