  const rank=RANKS[placeInfo(source).rank],own=t.owner===uid,protection=t.protectionUntil>now;
  const pending=Object.values(view.requests).filter(r=>r.applicant===uid&&r.status==='pending');
  $('command-content').innerHTML=before+`<div class="territory-heading"><h3>${esc(placeInfo(source).ko)}</h3><span class="rank-badge">${rank.name}</span></div><p class="territory-owner">${t.owner?'군주 <strong>'+esc(playerName(t.owner))+'</strong>':'<strong>중립 수비대</strong>'}${own?' · 내 영토':''}</p><div class="territory-stats"><span>주둔 병력<strong>${t.units.length} / ${capacityOf(t.id,view,now)}</strong></span><span>인접 영토<strong>${MAP.layout.cells.find(c=>c.id===source).neighbors.length}곳</strong></span><span>다음 행동<strong>${own?(t.actionReadyAt>now?clockText(t.actionReadyAt-now):'지금 가능'):'—'}</strong></span><span>다음 충원<strong>${t.owner?(nextRecruitAt(t)?clockText(nextRecruitAt(t)-now):'정원 도달'):'없음'}</strong></span></div>${protection?`<div class="start-protection">시작 보호 ${clockText(t.protectionUntil-now)} 남음${own?'<br>먼저 공격하면 보호가 해제됩니다.':''}</div>`:''}${revivalButton(t,own)}${roster(t,own)}${own?roleControlsHTML(view,t,now,busy):''}${own?'<p class="cooldown-note">장수만 이동: 개인 10분 대기 · 공격/병사 동반: 영토 10분 대기</p>':''}${pending.length?pending.map(r=>`<p class="pending-note">${esc(placeInfo(r.territoryId).ko)} 양도 승인 기다리는 중</p>`).join(''):''}`;
