function renderRevival(){
  if(!revival||modalKind!=='revive')return;
  const previousScroll=document.querySelector('.revival-roster')?.scrollTop||0;
  const t=view.territories[revival.territoryId];
  if(!t||t.owner!==uid){$('modal-content').innerHTML='<div class="modal-inner"><h2>영토의 주인이 바뀌었습니다.</h2><p>다른 내 영토에서 다시 선택해 주세요.</p><button class="primary-button" data-close>확인</button></div>';return;}
  if(revival.revision!==world.territories[t.id].revision){revival.revision=world.territories[t.id].revision;revival.error='전황이 바뀌어 최신 병력으로 갱신했습니다. 선택한 병력을 다시 확인해 주세요.';}
  const now=currentTime(),available=t.units.filter(u=>u.sides!==20&&u.readyAt<=now);revival.ids=new Set([...revival.ids].filter(id=>available.some(u=>u.id===id)));
  revival.readySignature=JSON.stringify([t.actionReadyAt<=now,available.map(u=>u.id)]);
  const chosen=available.filter(u=>revival.ids.has(u.id)),total=chosen.reduce((n,u)=>n+u.sides,0),error=validateRevival(view,uid,t.id,[...revival.ids],now);
  $('modal-content').innerHTML=`<div class="modal-inner revival-modal"><div class="modal-heading"><div><p class="eyebrow">다시 드는 군주의 깃발</p><h2>${esc(placeInfo(t.id).ko)} · 군주 살리기</h2></div><button class="close-button" data-close aria-label="닫기">×</button></div><p>선택한 병력을 소모하고 군주 D20을 되살립니다.<br>주사위 면수 합계가 20 이상이어야 합니다. 초과한 수치는 반환하지 않습니다.</p><div class="revival-roster">${available.map(u=>`<label class="revival-unit ${revival.ids.has(u.id)?'checked':''}"><input type="checkbox" data-revive-unit="${esc(u.id)}" ${revival.ids.has(u.id)?'checked':''} ${busy?'disabled':''}>${portraitHTML(u)}<span>${esc(u.name)}<small>D${u.sides}${effectOf(u)?' · '+esc(effectOf(u).title):''}</small></span></label>`).join('')||'<p>행동 가능한 교환 병력이 없습니다.</p>'}</div><div class="revival-total"><span>선택 ${chosen.length}명 · 교환 후 ${t.units.length-chosen.length+1}명</span><strong>${total} / 20</strong></div><p class="ruler-name-error" role="alert">${esc(revival.error||error||'')}</p><p class="rules-footnote">부활은 이 영토의 행동 1회입니다. 영토와 군주는 10분 뒤 행동할 수 있습니다.</p><button class="primary-button" data-revive-submit ${error||busy||!store?.connected?'disabled':''}>병력 ${chosen.length}명과 교환해 살리기</button></div>`;
  document.querySelector('.revival-roster').scrollTop=previousScroll;
}
async function confirmRevival(){
  if(!revival||busy)return;const context=revival;
  await run(async()=>{await store.submit({type:'revive',territoryId:context.territoryId,unitIds:[...context.ids],expectedTerritories:{[context.territoryId]:context.revision}});closeModal();revival=null;selected.clear();target=null;toast('군주가 부활했습니다. 10분 뒤 다음 행동이 가능합니다.');},message=>{if(revival){revival.error=message;renderRevival();}});
  if(modalKind==='revive')renderRevival();if(modalKind==='officer')renderOfficerDetail();if(modalKind==='gallery')renderGallery();
}

