let seasonHistory=null,seasonHistoryMap=null,seasonHistoryLoading=false,seasonSwitching=false,forcedArchive=false;
function syncSeasonUI(){
  const local=store?.mode==='practice'||sessionStorage.getItem('samguk-online-mode')==='practice',now=currentTime(),phase=seasonPhase(now),banner=$('season-banner');
  if(local){banner.hidden=true;document.body.classList.remove('is-season-break');return;}
  banner.hidden=false;const html=seasonMessage(now)+' <button id="past-seasons">삼국지 지난 역사</button>';
  if(banner.innerHTML!==html){banner.innerHTML=html;$('past-seasons').onclick=()=>showSeasonHistory();}
  document.body.classList.toggle('is-season-break',phase==='break');
  if(phase==='break'){
    if($('modal').open){$('modal').close();modalKind='';}
    forcedArchive=true;if($('season-history').hidden&&!seasonHistoryLoading)showSeasonHistory();
  }else if(phase==='season1'){
    if(forcedArchive){$('season-history').hidden=true;forcedArchive=false;}
    if(store?.mode==='online'&&store.config.worldId!=='season-1'&&!seasonSwitching&&!busy){seasonSwitching=true;googleLogin(true).finally(()=>{seasonSwitching=false;});}
  }
}
async function showSeasonHistory(){
  if(seasonPhase(currentTime())==='test'){toast('최종 기록은 오늘 11:00 시즌 종료 후 열립니다.');return;}
  const panel=$('season-history');panel.hidden=false;panel.dataset.tab='map';
  const heading=`<header><div><h1>삼국지 지난 역사</h1><p>테스트 시즌 · 2026년 10월 28일 11:00 종료<br>시즌 1 · 오늘 12:00 개막 · 최종 랭킹과 결과 지도만 보존합니다.</p></div>${seasonPhase(currentTime())==='season1'?'<button id="leave-history">시즌 1로 돌아가기</button>':''}</header>`;
  panel.innerHTML=heading+'<p>최종 기록을 불러오고 있습니다.</p>';
  if($('leave-history'))$('leave-history').onclick=()=>panel.hidden=true;
  if(!uid||!store?.sdk){panel.innerHTML=heading+'<div class="season-auth"><p>Google 로그인 후 최종 기록을 볼 수 있습니다.</p><button id="season-history-login">Google로 기록 보기</button></div>';$('season-history-login').onclick=async()=>{await googleLogin(false);await showSeasonHistory();};return;}
  seasonHistoryLoading=true;
  try{
    if(!seasonHistory){const snap=await store.sdk.get(store.sdk.ref(store.db,'worlds/main'));if(!snap.exists())throw Error('테스트 시즌 기록이 없습니다.');seasonHistory=archiveTestSeason(snap.val());}
    seasonHistoryMap?.observer.disconnect();
    panel.innerHTML=heading+`<div class="season-tab-buttons"><button data-season-tab="map">최종 지도</button><button data-season-tab="ranking">최종 랭킹</button></div><div class="season-record-layout"><div class="season-record-map map-card" id="season-record-map"><div class="map-toolbar"><strong>테스트 시즌 최종 결과 지도</strong><div><button data-zoom="out">−</button><button data-zoom="all" data-map-zoom>전체</button><button data-zoom="in">＋</button></div></div><div class="map-viewport"><svg aria-label="테스트 시즌 최종 결과 지도"></svg></div><p id="season-map-caption">영토를 선택하면 최종 소유자와 주둔 인원을 확인합니다.</p></div><aside class="season-record-ranking"><h2>최종 랭킹</h2>${seasonHistory.rankings.map(p=>`<article><strong>${p.rank}위 · <i style="color:${COLORS[p.color]}">●</i> ${esc(p.name)}</strong><small>영토 ${p.territories}곳 · 병력 ${p.army}명<br>처치 ${p.kills} · 전사 ${p.deaths}</small></article>`).join('')||'<p>참가 기록 없음</p>'}</aside></div>`;
    const archiveWorld=archiveMapWorld(seasonHistory);
    seasonHistoryMap=new TerritoryMap($('season-record-map'),id=>{const t=archiveWorld.territories[id];$('season-map-caption').textContent=`${placeInfo(id).ko} · ${archiveWorld.players[t.owner]?.name||'중립'} · 최종 주둔 ${t.units.length}명`;});
    seasonHistoryMap.setWorld(archiveWorld,null,null,null);
    panel.querySelectorAll('[data-season-tab]').forEach(b=>b.onclick=()=>{panel.dataset.tab=b.dataset.seasonTab;seasonHistoryMap.build();});
    if($('leave-history'))$('leave-history').onclick=()=>panel.hidden=true;
  }catch(error){panel.innerHTML=heading+`<p>${esc(error.message)}</p><button id="retry-season-history">다시 불러오기</button>`;$('retry-season-history').onclick=()=>showSeasonHistory();}
  finally{seasonHistoryLoading=false;}
}
